    fit_reEi800GP.(cut_names{i}) = fr_800const_bg;

    acolor g
    bg_data = extract_bg_par(fr_800const_bg.all_fit_par,[1,2]);
    % original slope parameters
    pd(bg_data(1));lx(fr_800const_bg.all_fit_par(1).en,fr_800const_bg.all_fit_par(end).en);keep_figure; ly 0 0.5; %[output:5c766a05]
